fn interval(values:&[f64])->Value{assert_eq!(values.len(),15);let mut a=values.to_vec();a.sort_by(f64::total_cmp);json!({"median":a[7],"low":a[3],"high":a[11],"wins":values.iter().filter(|v|**v<1.).count(),"ratios":values,"conditional_nominal_coverage":0.96484375})}
