    let jobs=read(r("jobs.json"));let mut prior:BTreeSet<String>=serde_json::from_value(read(r("prior-proof-sha256.json"))).unwrap();assert_eq!(prior.len(),22366);let mut inventory=Vec::new();let mut rows=Vec::new();let mut counters=BTreeMap::new();let mut profiles=BTreeMap::new();let mut symbols_all=BTreeMap::new();let mut vk=BTreeMap::new();
