            assert_eq!(pids.len(),1);assert!(count>0);let unknown=categories.get("unknown").copied().unwrap_or(0)as f64/period as f64;let category_shares=categories.iter().map(|(cat,p)|(cat.clone(),json!({"period":p,"share":*p as f64/period as f64}))).collect::<BTreeMap<_,_>>();let symbol_rows=symbols.iter().map(|(s,(count,period))|json!({"symbol":s,"samples":count,"period":period})).collect::<Vec<_>>();symbols_all.insert(n.to_string(),json!(symbol_rows));profiles.insert(n.to_owned(),json!({"case":c["name"],"variant":j["variant"],"samples":count,"period":period,"PIDs":pids,"TIDs":tids,"categories":category_shares,"new_queue_drain_context_period":selected,"unknown_period_share":unknown,"attribution_qualified":count>=1000&&unknown<=0.05,"zero_lost":true,"absolute_period_coverage_not_validated":true}));
